+  const urls = [];
+  for (const pattern of [IMAGE_MARKDOWN, IMAGE_HTML]) {
+    pattern.lastIndex = 0;
+    for (const match of body.matchAll(pattern)) {
+      const url = match[1];
+      if (url && !urls.includes(url))
